# Tendora's small, replayable workbench. Requires only zsh's bundled modules.
# Event files are data. They are never sourced or evaluated as shell code.

fail() { print -ru2 -- "tendora: $*"; return 1; }

valid_id() {
  [[ ${#1} -le 40 && $1 == [a-z][a-z0-9-]# ]]
}

valid_text() {
  [[ -n $1 && ${#1} -le 2000 && $1 != *[[:cntrl:]]* ]]
}

reset_projection() {
  typeset -gi sequence=0 material_revision=0
  typeset -g purpose=''
  typeset -gA q_title=() q_state=()
  typeset -gA p_target=() p_next=() p_reason=() p_evidence=()
  typeset -gA p_verdict=() p_basis=() p_enacted=()
}

# Pure rehearsal: reads the projection; does not change it or run commands.
# The one active place is an intentional constraint: finish, park, or choose.
evaluate_proposal() {
  local proposal=$1 question=${p_target[$1]} current next other
  typeset -g verdict=blocked decision=''
  if [[ -n ${p_enacted[$proposal]} ]]; then
    decision='This proposal has already been enacted.'; return
  fi
  current=${q_state[$question]}
  next=${p_next[$proposal]}
  case "$current:$next" in
    open:active|open:parked|active:resolved|active:parked|parked:open|resolved:open) ;;
    *) decision="Transition $current -> $next is not allowed."; return ;;
  esac
  if [[ $next == active ]]; then
    for other in ${(ok)q_state}; do
      if [[ ${q_state[$other]} == active && $other != $question ]]; then
        decision="The active place belongs to $other; finish or park it first."
        return
      fi
    done
  fi
  if [[ $next == resolved && ${p_evidence[$proposal]} == - ]]; then
    decision='Resolution needs an evidence statement.'; return
  fi
  verdict=pass
  decision="Allowed: $question moves from $current to $next."
}

# Ten newline-terminated fields, with control characters forbidden in each.
# Strict replay is also the validator used before publishing a new receipt.
apply_event_file() {
  local file=$1 line
  local -a fields=()
  while IFS= read -r line; do
    fields+=("$line")
    (( ${#fields} <= 10 )) || { fail "Too many fields in $file"; return 1; }
  done < "$file"
  [[ -z $line ]] || { fail "Unterminated field in $file"; return 1; }
  (( ${#fields} == 10 )) || { fail "Incomplete receipt: $file"; return 1; }
  for line in "${fields[@]}"; do
    valid_text "$line" || { fail "Invalid field in $file"; return 1; }
  done
  local format=$fields[1] seq=$fields[2] epoch=$fields[3] kind=$fields[4]
  local id=$fields[5] target=$fields[6] value=$fields[7]
  local reason=$fields[8] evidence=$fields[9] basis=$fields[10]
  [[ $format == tendora.event.v1 && $seq == $((sequence + 1)) && $epoch == <1-> ]] || {
    fail "Invalid header or sequence in $file"; return 1
  }
  [[ $basis == "$material_revision" ]] || {
    fail "Receipt has the wrong material revision: $file"; return 1
  }
  if (( sequence == 0 )); then
    [[ $kind == genesis ]] || { fail 'The first receipt must be genesis.'; return 1; }
  elif [[ $kind == genesis ]]; then
    fail 'Genesis can happen only once.'; return 1
  fi
  case $kind in
    genesis)
      [[ $id == world && $target == - && $value == 1 ]] || {
        fail 'Invalid genesis receipt.'; return 1
      }
      purpose=$reason
      (( material_revision++ ))
      ;;
    question)
      valid_id "$id" && [[ -z ${q_title[$id]} && $target == - && $value == open && $evidence == - ]] || {
        fail 'Invalid or duplicate question.'; return 1
      }
      q_title[$id]=$reason
      q_state[$id]=open
      (( material_revision++ ))
      ;;
    proposal)
      valid_id "$id" && valid_id "$target" && [[ -z ${p_target[$id]} && -n ${q_title[$target]} ]] || {
        fail 'Invalid proposal ID or unknown question.'; return 1
      }
      [[ $value == (open|active|parked|resolved) ]] || { fail 'Unknown question state.'; return 1; }
      p_target[$id]=$target
      p_next[$id]=$value
      p_reason[$id]=$reason
      p_evidence[$id]=$evidence
      ;;
    rehearsal)
      [[ -n ${p_target[$id]} && $target == ${p_target[$id]} && $evidence == - ]] || {
        fail 'Rehearsal refers to an unknown or different proposal.'; return 1
      }
      evaluate_proposal "$id"
      [[ $value == "$verdict" && $reason == "$decision" ]] || {
        fail 'Rehearsal disagrees with the laws.'; return 1
      }
      p_verdict[$id]=$value
      p_basis[$id]=$basis
      ;;
    enactment)
      [[ -n ${p_target[$id]} && $target == ${p_target[$id]} && $value == ${p_next[$id]} &&
         $reason == ${p_reason[$id]} && $evidence == ${p_evidence[$id]} &&
         ${p_verdict[$id]} == pass && ${p_basis[$id]} == "$material_revision" ]] || {
        fail 'Enactment needs a matching, passing, current rehearsal.'; return 1
      }
      evaluate_proposal "$id"
      [[ $verdict == pass ]] || { fail "$decision"; return 1; }
      q_state[$target]=$value
      p_enacted[$id]=$seq
      (( material_revision++ ))
      ;;
    observation)
      [[ $id == world && ( $target == world || -n ${q_title[$target]} ) && $value == note && $evidence == - ]] || {
        fail 'Invalid observation target.'; return 1
      }
      ;;
    *) fail "Unknown event type: $kind"; return 1 ;;
  esac
  sequence=$seq
  return 0
}

load_world() {
  reset_projection
  local file expected
  for file in "$state_dir/events"/*(DN); do
    printf -v expected '%010d.event' $((sequence + 1))
    [[ ${file:t} == "$expected" && -f $file && ! -L $file ]] || {
      fail "Unexpected receipt or gap: $file"; return 1
    }
    apply_event_file "$file" || return 1
  done
}

publish_event() {
  # Both paths are on the same filesystem. The process holds the exclusive lock.
  mv -- "$1" "$2"
}

append_event() {
  local kind=$1 id=$2 target=$3 value=$4 reason=$5 evidence=$6
  local filename destination staging next_seq=$((sequence + 1))
  (( next_seq <= 9999999999 )) || { fail 'Receipt sequence is exhausted.'; return 1; }
  printf -v filename '%010d.event' "$next_seq"
  destination="$state_dir/events/$filename"
  # $$ stays constant in zsh subshells; sysparams[pid] is the actual writer.
  staging="$state_dir/staging/$next_seq-${sysparams[pid]}-$RANDOM.pending"
  [[ ! -e $destination && ! -L $destination ]] || { fail 'Receipt already exists.'; return 1; }
  (
    setopt noclobber
    print -rl -- tendora.event.v1 "$next_seq" "$EPOCHSECONDS" "$kind" "$id" \
      "$target" "$value" "$reason" "$evidence" "$material_revision" > "$staging"
  ) || { fail 'Could not stage receipt.'; return 1; }
  apply_event_file "$staging" || return 1
  publish_event "$staging" "$destination" || { fail 'Could not publish receipt.'; return 1; }
  print -r -- "Receipt $filename: $kind $id"
}

show_status() {
  local id place='empty' freshness
  local -a pending=("$state_dir/staging"/*(DN))
  print -r -- "$purpose"
  print -r -- "Receipts: $sequence | Material revision: $material_revision"
  for id in ${(ok)q_state}; do
    [[ ${q_state[$id]} == active ]] && place=$id
  done
  print -r -- "Active place: $place (capacity 1)"
  print
  print -r -- 'Questions:'
  for id in ${(ok)q_title}; do
    printf '  %-10s %-22s %s\n' "${q_state[$id]}" "$id" "${q_title[$id]}"
  done
  print
  print -r -- 'Unenacted proposals:'
  for id in ${(ok)p_target}; do
    [[ -n ${p_enacted[$id]} ]] && continue
    freshness='not rehearsed'
    if [[ -n ${p_verdict[$id]} ]]; then
      freshness=${p_verdict[$id]}
      [[ ${p_basis[$id]} != "$material_revision" ]] && freshness="stale $freshness"
    fi
    print -r -- "  $id: ${p_target[$id]} -> ${p_next[$id]} [$freshness]"
  done
  (( ${#pending} )) && print -r -- "Uncommitted staging files: ${#pending}; ignored, retained for inspection."
  print
  print -r -- 'Read CONTINUE.md for the next human-sized step. This workbench starts no background worker.'
}

show_log() {
  local file line
  local -a fields
  for file in "$state_dir/events"/*(N); do
    fields=()
    while IFS= read -r line; do fields+=("$line"); done < "$file"
    print -r -- "#$fields[2] @$fields[3] $fields[4] $fields[5] -> $fields[6] ($fields[7])"
    print -r -- "  $fields[8]"
    [[ $fields[9] != - ]] && print -r -- "  Evidence / provenance: $fields[9]"
  done
  return 0
}

usage() {
  print -r -- 'Tendora — a workbench that remembers its choices.

  status                             Read the current world (default).
  verify                             Replay and validate every receipt.
  log                                Read the history.
  init [purpose]                     Begin a new world; never reset one.
  ask ID "question"                  Add an open question.
  propose ID QUESTION STATE "why" ["evidence"]
                                     Offer a state change.
  rehearse PROPOSAL                  Record a simulation; exit 3 if blocked.
  enact PROPOSAL                     Apply a fresh, passing rehearsal.
  observe QUESTION|world "finding"   Preserve an observation.

States: open, active, parked, resolved. See LAWS.md for transitions.
Quote text. Text has one line, at most 2,000 characters, no control characters.
IDs start with a lowercase letter and contain lowercase letters, digits, hyphens.
Evidence is an operator statement, not automatically verified proof.
TENDORA_STATE_DIR selects an independent state directory for experiments.'
}

tendora_main() {
  emulate -L zsh
  setopt extendedglob localtraps pipefail
  umask 077
  local command=${1:-status}
  (( $# )) && shift
  if [[ $command == (help|--help|-h) ]]; then usage; return 0; fi
  case $command in
    init) (( $# <= 1 )) || { usage; return 2; } ;;
    status|verify|log) (( $# == 0 )) || { usage; return 2; } ;;
    ask|observe) (( $# == 2 )) || { usage; return 2; } ;;
    propose) (( $# == 4 || $# == 5 )) || { usage; return 2; } ;;
    rehearse|enact) (( $# == 1 )) || { usage; return 2; } ;;
    *) usage; return 2 ;;
  esac
  zmodload zsh/files && zmodload zsh/system && zmodload zsh/datetime || {
    fail 'This zsh needs its files, system, and datetime modules.'; return 1
  }
  local state_dir=${TENDORA_STATE_DIR:-$TENDORA_ROOT/state}
  state_dir=${state_dir:a}
  local directory lock_fd argument
  for argument in "$@"; do
    valid_text "$argument" || { fail 'Arguments must be nonempty, single-line text (maximum 2,000 characters).'; return 2; }
  done
  if [[ $command == init ]]; then
    [[ ! -L $state_dir ]] || { fail 'State directory must not be a symlink.'; return 1; }
    mkdir -p -- "$state_dir" || return 1
  fi
  [[ -d $state_dir && ! -L $state_dir ]] || { fail 'No world here. Run init first.'; return 1; }
  for directory in events staging; do
    [[ ! -L $state_dir/$directory ]] || { fail "Symlink at $directory is not allowed."; return 1; }
    # Empty runtime directories may be absent in a file-only copy or checkout.
    # Only staging is disposable; a missing committed event directory is fatal.
    if [[ $command == init || $directory == staging ]]; then
      mkdir -p -- "$state_dir/$directory" || return 1
    fi
    [[ -d $state_dir/$directory ]] || { fail "Missing $directory directory."; return 1; }
  done
  [[ ! -L $state_dir/lock && ( ! -e $state_dir/lock || -f $state_dir/lock ) ]] || {
    fail 'Lock must be a regular file.'; return 1
  }
  : >> "$state_dir/lock" || return 1
  zsystem flock -t 0 -f lock_fd "$state_dir/lock" || {
    fail 'The workbench is busy. Try again after the current operation.'; return 1
  }
  # EXIT runs after this function's locals go out of scope when sourced.
  # Capture the numeric descriptor now, not a reference to the local variable.
  trap "zsystem flock -u $lock_fd" EXIT
  load_world || return 1
  if [[ $command != init && $sequence == 0 ]]; then
    fail 'No genesis receipt. Run init first.'; return 1
  fi
  case $command in
    init)
      if (( sequence )); then
        print -r -- "World already exists; $sequence receipts preserved."
      else
        append_event genesis world - 1 "${1:-Keep this workbench understandable, testable, and resumable.}" \
          'Inherited reference c986990; its contents were not available in this world.'
      fi
      ;;
    status) show_status ;;
    verify)
      local -a pending=("$state_dir/staging"/*(DN))
      print -r -- "Verified $sequence receipts; material revision $material_revision."
      print -r -- "${#pending} uncommitted staging files ignored. Verification checks structure and laws, not authenticity."
      ;;
    log) show_log ;;
    ask)
      valid_id "$1" && [[ -z ${q_title[$1]} ]] || { fail 'Question ID is invalid or already exists.'; return 2; }
      append_event question "$1" - open "$2" -
      ;;
    propose)
      valid_id "$1" && valid_id "$2" && [[ -z ${p_target[$1]} && -n ${q_title[$2]} ]] || {
        fail 'Proposal ID is invalid, already exists, or question is unknown.'; return 2
      }
      [[ $3 == (open|active|parked|resolved) ]] || { fail 'Unknown target state.'; return 2; }
      append_event proposal "$1" "$2" "$3" "$4" "${5:--}"
      ;;
    rehearse)
      valid_id "$1" && [[ -n ${p_target[$1]} ]] || { fail 'Unknown proposal.'; return 2; }
      evaluate_proposal "$1"
      append_event rehearsal "$1" "${p_target[$1]}" "$verdict" "$decision" - || return 1
      print -r -- "$verdict: $decision"
      [[ $verdict == pass ]] || return 3
      ;;
    enact)
      valid_id "$1" && [[ -n ${p_target[$1]} ]] || { fail 'Unknown proposal.'; return 2; }
      [[ ${p_verdict[$1]} == pass && ${p_basis[$1]} == "$material_revision" ]] || {
        fail 'Rehearse this proposal against the current material revision first.'; return 2
      }
      evaluate_proposal "$1"
      [[ $verdict == pass ]] || { fail "$decision"; return 2; }
      append_event enactment "$1" "${p_target[$1]}" "${p_next[$1]}" "${p_reason[$1]}" "${p_evidence[$1]}"
      ;;
    observe)
      [[ $1 == world || -n ${q_title[$1]} ]] || { fail 'Unknown observation target.'; return 2; }
      append_event observation world "$1" note "$2" -
      ;;
  esac
}

#!/usr/bin/env zsh
# Also works as: (source ./tendora.zsh status)
(
  emulate -LR zsh
  setopt extendedglob pipefail
  typeset TENDORA_ROOT=${${(%):-%x}:A:h}
  source "$TENDORA_ROOT/lib/world.zsh" || exit 1
  tendora_main "$@"
)
